INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C1','kor',2,1,'u3',1,'꾸며 주는 말의 뜻과 좋은 점 — 「넓은」, 「활짝」처럼 뒤에 오는 말을 꾸며 그 뜻을 자세하게 해 주는 말임을 알고, 글 ㉮·㉯를 견주어 실감 나고 자세하며 읽는 재미를 준다는 점 알기',ARRAY['2국03-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C2','kor',2,1,'u3',1,'일기란 무엇인가 — 그날 겪은 일 가운데 기억하고 싶은 일과 그에 대한 생각이나 느낌을 쓰는 글이며, 추억을 기록하고 나를 되돌아보게 함을 알기',ARRAY['2국03-04']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C3','kor',2,1,'u3',3,'그림에 어울리는 꾸며 주는 말 고르기 — 색깔·모양·모습 가운데 무엇에 눈길을 두는지에 따라 노란/예쁜, 튼튼한/멋진 등을 고르고 그 까닭 말하기',ARRAY['2국03-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C4','kor',2,1,'u3',3,'꾸며 주는 말을 넣어 문장 만들기 — 뒤에 오는 말(빨간 딸기 / 빠르게 달린다)에 맞는 꼴로 넣고, 한 문장에 여러 개(멋있는 말이 힘차게) 넣어 사진을 설명하기',ARRAY['2국04-03']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C5','kor',2,1,'u3',5,'「식물은 어떻게 자랄까?」 내용 파악 — 땅콩(노란 꽃, 땅속 열매)·포도(덩굴손, 탐스러운 열매)·개구리밥(물 위, 이름의 까닭)이 자라는 모습 찾기',ARRAY['2국03-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C6','kor',2,1,'u3',5,'모양을 꾸며 주는 말의 뜻 — 활짝·조롱조롱·올록볼록·우수수 같은 말의 뜻을 글 속 문장과 이어 짐작하기',ARRAY['2국04-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C7','kor',2,1,'u3',5,'글 속 꾸며 주는 말로 문장 쓰고 읽기 — 쑥쑥·고소한·올록볼록·탐스러운 등을 찾아 무엇을 꾸미는지 살피고 새 문장을 만들어 소리 내어 읽기',ARRAY['2국03-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C8','kor',2,1,'u3',7,'겪은 일을 시간·장소에 따라 정리하기 — 아침·낮·저녁, 집·학교·도서관으로 나누고 한 것·본 것·들은 것과 그때의 생각이나 느낌 찾기',ARRAY['2국03-04']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C9','kor',2,1,'u3',7,'인상 깊은 일과 일기 글감 정하기 — 가장 기억에 남는 일(인상 깊은 일)이 글감이 됨을 알고, 한 것·본 것·들은 것 → 기뻤던·슬펐던·화났던 일 → 가장 인상 깊은 일 고르기',ARRAY['2국03-04']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C10','kor',2,1,'u3',7,'일기 제목 정하기 — 일기 내용을 대표하거나 중요한 일·인물, 생각이나 느낌을 넣어 겪은 일이 잘 드러나게 제목 붙이기',ARRAY['2국03-04']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C11','kor',2,1,'u3',9,'겪은 일이 잘 드러나게 일기 쓰기 — 날짜·요일·날씨를 쓰고 언제·어디에서·누구와·무슨 일을 구체적으로, 생각이나 느낌을 솔직하게 꾸며 주는 말을 넣어 쓴 뒤 점검표로 스스로 확인하기',ARRAY['2국03-04']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C12','kor',2,1,'u3',12,'여러 가지 일기 쓰기 — 식물 관찰 일기(이름·특징을 넣은 제목, 오감 관찰, 꾸며 주는 말), 요리 일기·성장 일기책·만화 일기처럼 다양한 주제와 형식으로 쓰기',ARRAY['2국03-04']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C13','kor',2,1,'u3',12,'느낌을 나타내는 말과 장면 꾸미기 — 톡톡·빙글빙글·시원한·귀여운으로 장면을 설명하고, 보드레하다·찐득찐득하다·부들부들하다·만질만질하다 같은 느낌을 나타내는 말의 뜻 알기(정리·기초 다지기)',ARRAY['2국03-02']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X01','kor',2,'u3',ARRAY['K2-1-u3-C1','K2-1-u3-C3']::text[],'꾸며 주는 말이 있어도 없어도 뜻과 느낌이 똑같다고 여긴다','넣은 문장과 뺀 문장을 견주어 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X02','kor',2,'u3',ARRAY['K2-1-u3-C1','K2-1-u3-C7']::text[],'꾸밈을 받는 말(할머니·옥수수밭·땅콩)을 꾸며 주는 말로 안다','「어떤?」, 「어떻게?」에 답하는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X03','kor',2,'u3',ARRAY['K2-1-u3-C3','K2-1-u3-C13']::text[],'그림·장면과 어울리지 않는 꾸며 주는 말을 고른다','그림을 다시 보고 색·모양·움직임 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X04','kor',2,'u3',ARRAY['K2-1-u3-C4']::text[],'뒤에 오는 말과 맞지 않는 꼴의 꾸며 주는 말을 넣는다(빠르게 딸기, 귀여운 달린다)','무엇을 꾸미나? 이름 앞 / 움직임 앞') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X05','kor',2,'u3',ARRAY['K2-1-u3-C4','K2-1-u3-C7']::text[],'한 문장에는 꾸며 주는 말을 하나만 넣을 수 있다고 여긴다','여러 곳을 꾸며도 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X06','kor',2,'u3',ARRAY['K2-1-u3-C5']::text[],'글에 없는 내용으로 답하거나 식물 정보를 바꿔 안다','그 문장을 글에서 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X07','kor',2,'u3',ARRAY['K2-1-u3-C6','K2-1-u3-C13']::text[],'모양이나 느낌을 나타내는 말의 뜻을 헷갈린다','글 속 문장에 넣어 장면 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X08','kor',2,'u3',ARRAY['K2-1-u3-C2','K2-1-u3-C9']::text[],'일기는 하루에 있었던 일을 처음부터 끝까지 모두 늘어놓는 글이라 여긴다','가장 인상 깊은 일 하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X09','kor',2,'u3',ARRAY['K2-1-u3-C9']::text[],'일기 글감은 아주 특별한 일이어야 한다고 여긴다','반복되는 하루에서도 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X10','kor',2,'u3',ARRAY['K2-1-u3-C2','K2-1-u3-C11']::text[],'겪은 일만 쓰고 그에 대한 생각이나 느낌을 빠뜨린다','「그때 내 마음은?」 한 줄') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X11','kor',2,'u3',ARRAY['K2-1-u3-C8']::text[],'한 것·본 것·들은 것을 헷갈려 나눈다','내가 했나? 봤나? 들었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X12','kor',2,'u3',ARRAY['K2-1-u3-C10','K2-1-u3-C12']::text[],'제목을 날짜나 「일기」처럼 내용과 관계없이 붙인다','중요한 일·생각을 담아 제목') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X13','kor',2,'u3',ARRAY['K2-1-u3-C11']::text[],'언제·어디에서·누구와·무슨 일을 두루뭉술하게 쓴다','지난주 → 토요일 → 오전 10시쯤') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X14','kor',2,'u3',ARRAY['K2-1-u3-C11','K2-1-u3-C12']::text[],'날짜와 날씨 가운데 하나만 쓰거나 날씨를 「맑음」처럼 짧게만 쓴다','날짜·요일·날씨 모두, 날씨는 생생하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X15','kor',2,'u3',ARRAY['K2-1-u3-C9','K2-1-u3-C11']::text[],'좋았던 일만 일기에 써야 한다고 여겨 슬프거나 억울한 일은 쓰지 않는다','억울한 일도 솔직하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
