INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#3','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C5',3,'ox','auto','「개구리밥」은 개구리가 먹는 밥이라서 붙은 이름이다.',ARRAY['K2-1-u3-X06']::text[],false,'{"seq":3,"concept":"K2-1-u3-C5","difficulty":3,"kind":"ox","stem":"「개구리밥」은 개구리가 먹는 밥이라서 붙은 이름이다.","answer":"X","reason_options":[{"t":"개구리가 물속에서 나올 때 입가에 밥풀처럼 붙는다고 붙은 이름이라서","correct":true},{"t":"개구리가 즐겨 먹는 풀이라서","mis":"K2-1-u3-X06"}],"mis":"K2-1-u3-X06","explanation":["먹는 밥이 아니에요.","90쪽이에요.","글에서 짚어요."],"asset":{"type":"passage","lines":["땅콩은 새싹이 쑥쑥 자라 노란 꽃을 피워요.","열매는 땅속에서 맺혀요. 올록볼록 껍데기 속에 고소한 땅콩이 있어요.","포도는 덩굴손이 버팀대를 감고 뻗어 가요.","송알송알 보랏빛 포도가 탐스럽게 열려요.","개구리밥은 물 위에 떠서 자라는 풀이에요.","개구리가 물에서 나올 때 입가에 밥풀처럼 붙는다고 붙은 이름이래요."],"title":"『국어』 80~91쪽 「식물은 어떻게 자랄까?」(유다정) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
