INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#5','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C6',3,'mc','auto','「땅속에서 조롱조롱 열매를 맺었구나.」를 읽고 떠오르는 모습은?',ARRAY['K2-1-u3-X07','K2-1-u3-X06']::text[],false,'{"seq":5,"concept":"K2-1-u3-C6","difficulty":3,"kind":"mc","stem":"「땅속에서 조롱조롱 열매를 맺었구나.」를 읽고 떠오르는 모습은?","options":[{"t":"작은 땅콩이 줄기에 많이 매달려 있는 모습","correct":true},{"t":"땅콩이 하나만 있는 모습","mis":"K2-1-u3-X07"},{"t":"땅콩이 하늘에 떠 있는 모습","mis":"K2-1-u3-X06"}],"explanation":["많이 매달렸어요.","82쪽이에요.","낱말 알기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#6','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C5',3,'mc','auto','이 글을 읽고 얻을 수 있는 가장 중요한 정보는?',ARRAY['K2-1-u3-X06']::text[],false,'{"seq":6,"concept":"K2-1-u3-C5","difficulty":3,"kind":"mc","stem":"이 글을 읽고 얻을 수 있는 가장 중요한 정보는?","options":[{"t":"식물마다 자라는 모습이 다양하다는 것","correct":true},{"t":"모든 식물은 똑같이 자란다는 것","mis":"K2-1-u3-X06"},{"t":"식물은 물에서만 자란다는 것","mis":"K2-1-u3-X06"}],"explanation":["다양해요.","지도서 133쪽이에요.","식물 정보예요."],"asset":{"type":"passage","lines":["땅콩은 새싹이 쑥쑥 자라 노란 꽃을 피워요.","열매는 땅속에서 맺혀요. 올록볼록 껍데기 속에 고소한 땅콩이 있어요.","포도는 덩굴손이 버팀대를 감고 뻗어 가요.","송알송알 보랏빛 포도가 탐스럽게 열려요.","개구리밥은 물 위에 떠서 자라는 풀이에요.","개구리가 물에서 나올 때 입가에 밥풀처럼 붙는다고 붙은 이름이래요."],"title":"『국어』 80~91쪽 「식물은 어떻게 자랄까?」(유다정) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#7','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C7',3,'mc','auto','「덩굴손이 꼬불꼬불 쭈욱,」을 대신할 다른 꾸며 주는 말로 알맞은 것은?',ARRAY['K2-1-u3-X03','K2-1-u3-X07']::text[],false,'{"seq":7,"concept":"K2-1-u3-C7","difficulty":3,"kind":"mc","stem":"「덩굴손이 꼬불꼬불 쭈욱,」을 대신할 다른 꾸며 주는 말로 알맞은 것은?","options":[{"t":"덩굴손이 구불구불 길게","correct":true},{"t":"덩굴손이 빨갛게 맛있게","mis":"K2-1-u3-X03"},{"t":"덩굴손이 우수수","mis":"K2-1-u3-X07"}],"explanation":["바꿔 쓸 수 있어요.","지도서 136쪽이에요.","비슷한 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#8','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C5',4,'sa','auto','덩굴손이 버팀대를 감고 뻗어 가는 나무에서 열리는 보랏빛 과일을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u3-C5","difficulty":4,"kind":"sa","stem":"덩굴손이 버팀대를 감고 뻗어 가는 나무에서 열리는 보랏빛 과일을 쓰세요.","answer":["포도"],"explanation":["포도예요.","86쪽이에요.","송알송알 열려요."],"asset":{"type":"passage","lines":["땅콩은 새싹이 쑥쑥 자라 노란 꽃을 피워요.","열매는 땅속에서 맺혀요. 올록볼록 껍데기 속에 고소한 땅콩이 있어요.","포도는 덩굴손이 버팀대를 감고 뻗어 가요.","송알송알 보랏빛 포도가 탐스럽게 열려요.","개구리밥은 물 위에 떠서 자라는 풀이에요.","개구리가 물에서 나올 때 입가에 밥풀처럼 붙는다고 붙은 이름이래요."],"title":"『국어』 80~91쪽 「식물은 어떻게 자랄까?」(유다정) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#9','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C7',4,'essay','teacher','93쪽 — 글에 나오는 꾸며 주는 말(쑥쑥·올록볼록·탐스러운·고소한 가운데 하나)을 골라 새 문장을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u3-C7","difficulty":4,"kind":"essay","stem":"93쪽 — 글에 나오는 꾸며 주는 말(쑥쑥·올록볼록·탐스러운·고소한 가운데 하나)을 골라 새 문장을 쓰세요.","answer_guide":{"answer":"예: 탐스러운 — 시골 할머니 댁 감나무에 탐스러운 감이 열렸다.","scoring_points":["글에 나오는 꾸며 주는 말을 골랐어요","그 말을 넣어 문장을 썼어요"]},"explanation":["새 문장이에요.","93쪽이에요.","소리 내어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#10','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C5',4,'essay','teacher','93쪽 다른 글과 이어 보기 — 식물이나 동물이 자라는 모습이 담긴 책이나 영상의 제목과 새롭게 안 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u3-C5","difficulty":4,"kind":"essay","stem":"93쪽 다른 글과 이어 보기 — 식물이나 동물이 자라는 모습이 담긴 책이나 영상의 제목과 새롭게 안 점을 쓰세요.","answer_guide":{"answer":"예: 「우리와 함께 살아가는 식물 이야기」 — 봄과 여름에 자라는 식물의 이름을 알 수 있었다.","scoring_points":["책이나 영상 제목을 썼어요","새롭게 안 점을 썼어요"]},"explanation":["새롭게 안 점이에요.","93쪽이에요.","예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#1','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C8',1,'mc','auto','소율이가 아침에 한 일은?',ARRAY['K2-1-u3-X11']::text[],false,'{"seq":1,"concept":"K2-1-u3-C8","difficulty":1,"kind":"mc","stem":"소율이가 아침에 한 일은?","options":[{"t":"교통 봉사를 해 주시는 분께 인사를 했다","correct":true},{"t":"운동장에서 달리기를 했다","mis":"K2-1-u3-X11"},{"t":"도서관에서 그림책을 읽었다","mis":"K2-1-u3-X11"}],"explanation":["인사했어요.","96쪽이에요.","아침이에요."],"asset":{"type":"passage","lines":["아침 — 맑은 하늘을 보고 기분이 좋았다. 교통 봉사하시는 분께 인사했다.","낮 — 화단에서 봄철 식물을 관찰하고, 운동장에서 달리기를 했다.","저녁 — 도서관에 가서 동생과 그림책을 읽었다."],"title":"『국어』 94~96쪽 소율이의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
