INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#6','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C8',2,'match','auto','소율이가 겪은 일과 시간을 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K2-1-u3-C8","difficulty":2,"kind":"match","stem":"소율이가 겪은 일과 시간을 이어 보세요.","pairs":[{"l":"아침","r":"교통 봉사하시는 분께 인사"},{"l":"낮","r":"운동장에서 달리기"},{"l":"저녁","r":"도서관에서 그림책 읽기"}],"mis":"K2-1-u3-X11","explanation":["시간 순서예요.","96쪽이에요.","정리해요."],"asset":{"type":"passage","lines":["아침 — 맑은 하늘을 보고 기분이 좋았다. 교통 봉사하시는 분께 인사했다.","낮 — 화단에서 봄철 식물을 관찰하고, 운동장에서 달리기를 했다.","저녁 — 도서관에 가서 동생과 그림책을 읽었다."],"title":"『국어』 94~96쪽 소율이의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#7','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C11',2,'mc','auto','소율이는 언제 어디에서 있었던 일을 일기로 썼나요?',ARRAY['K2-1-u3-X08']::text[],false,'{"seq":7,"concept":"K2-1-u3-C11","difficulty":2,"kind":"mc","stem":"소율이는 언제 어디에서 있었던 일을 일기로 썼나요?","options":[{"t":"수업 시간에 운동장에서 있었던 일","correct":true},{"t":"저녁에 도서관에서 있었던 일","mis":"K2-1-u3-X08"},{"t":"아침에 집에서 있었던 일","mis":"K2-1-u3-X08"}],"explanation":["운동장이에요.","97쪽 (1)이에요.","예시 답안이에요."],"asset":{"type":"passage","lines":["20○○년 4월 23일 수요일 · 날씨: 화창하게 맑은 날","오늘 수업 시간에 운동장에서 달리기를 했다.","선생님께서 출발하는 방법과 빠르게 달리는 방법을 가르쳐 주셨다.","나는 달리기를 좋아해서 열심히 연습했다. 연습이 끝나고 세 명씩 달리기를 했다.","출발선에 서 있는데 너무 긴장되고 떨렸다. 그래도 용기를 내서 끝까지 달렸다.","반 친구들이 박수를 치며 달리기를 잘한다고 칭찬해 주었다.","기분이 참 좋았다."],"title":"『국어』 97쪽 소율이가 쓴 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#8','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C10',2,'mc','auto','소율이 일기의 제목으로 알맞은 것은?',ARRAY['K2-1-u3-X12']::text[],false,'{"seq":8,"concept":"K2-1-u3-C10","difficulty":2,"kind":"mc","stem":"소율이 일기의 제목으로 알맞은 것은?","options":[{"t":"「떨렸지만 끝까지 달린 날」","correct":true},{"t":"「4월 23일」","mis":"K2-1-u3-X12"},{"t":"「일기」","mis":"K2-1-u3-X12"}],"explanation":["내용이 드러나요.","98쪽 5번이에요.","도우미 말이에요."],"asset":{"type":"passage","lines":["20○○년 4월 23일 수요일 · 날씨: 화창하게 맑은 날","오늘 수업 시간에 운동장에서 달리기를 했다.","선생님께서 출발하는 방법과 빠르게 달리는 방법을 가르쳐 주셨다.","나는 달리기를 좋아해서 열심히 연습했다. 연습이 끝나고 세 명씩 달리기를 했다.","출발선에 서 있는데 너무 긴장되고 떨렸다. 그래도 용기를 내서 끝까지 달렸다.","반 친구들이 박수를 치며 달리기를 잘한다고 칭찬해 주었다.","기분이 참 좋았다."],"title":"『국어』 97쪽 소율이가 쓴 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
