INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#5','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C11',3,'mc','auto','소율이는 겪은 일에 대해 어떤 생각이나 느낌이 들었나요?',ARRAY['K2-1-u3-X10']::text[],false,'{"seq":5,"concept":"K2-1-u3-C11","difficulty":3,"kind":"mc","stem":"소율이는 겪은 일에 대해 어떤 생각이나 느낌이 들었나요?","options":[{"t":"긴장되고 떨렸지만 친구들이 칭찬해 줘서 기분이 좋았어요","correct":true},{"t":"달리기가 싫어서 짜증이 났어요","mis":"K2-1-u3-X10"},{"t":"아무 느낌도 없었어요","mis":"K2-1-u3-X10"}],"explanation":["마음이 보여요.","97쪽 (3)이에요.","예시 답안이에요."],"asset":{"type":"passage","lines":["20○○년 4월 23일 수요일 · 날씨: 화창하게 맑은 날","오늘 수업 시간에 운동장에서 달리기를 했다.","선생님께서 출발하는 방법과 빠르게 달리는 방법을 가르쳐 주셨다.","나는 달리기를 좋아해서 열심히 연습했다. 연습이 끝나고 세 명씩 달리기를 했다.","출발선에 서 있는데 너무 긴장되고 떨렸다. 그래도 용기를 내서 끝까지 달렸다.","반 친구들이 박수를 치며 달리기를 잘한다고 칭찬해 주었다.","기분이 참 좋았다."],"title":"『국어』 97쪽 소율이가 쓴 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
