INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#9','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C11',4,'essay','teacher','104쪽 — 내가 고른 글감으로 날짜·날씨와 제목, 그렇게 정한 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u3-C11","difficulty":4,"kind":"essay","stem":"104쪽 — 내가 고른 글감으로 날짜·날씨와 제목, 그렇게 정한 까닭을 쓰세요.","answer_guide":{"answer":"예: 4월 26일 토요일, 바람이 살랑살랑 부는 날 / 제목: 아빠를 처음 이긴 날 / 까닭: 보드게임에서 처음으로 아빠를 이긴 일이 가장 기억에 남아서","scoring_points":["날짜와 날씨를 썼어요","제목과 까닭을 썼어요"]},"explanation":["일기 계획이에요.","104쪽이에요.","지도서 146쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#10','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C11',4,'essay','teacher','인상 깊은 일 하나로 꾸며 주는 말을 넣어 3~4문장의 일기를 쓰세요(생각이나 느낌 넣기).','{}'::text[],false,'{"seq":10,"concept":"K2-1-u3-C11","difficulty":4,"kind":"essay","stem":"인상 깊은 일 하나로 꾸며 주는 말을 넣어 3~4문장의 일기를 쓰세요(생각이나 느낌 넣기).","answer_guide":{"answer":"예: 오늘 점심시간에 짝과 운동장에서 줄넘기를 했다. 처음에는 줄이 자꾸 발에 걸렸다. 열 번을 넘게 쉬지 않고 넘었을 때 가슴이 콩닥콩닥 뛰었다. 정말 뿌듯했다.","scoring_points":["언제·어디에서·누구와·무엇을 썼어요","생각이나 느낌을 썼어요","꾸며 주는 말을 넣었어요"]},"explanation":["일기예요.","105쪽이에요.","평가 자료 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
