INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#7','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C13',3,'mc','auto','「동생의 피부가 만질만질하다.」의 뜻은?',ARRAY['K2-1-u3-X07']::text[],false,'{"seq":7,"concept":"K2-1-u3-C13","difficulty":3,"kind":"mc","stem":"「동생의 피부가 만질만질하다.」의 뜻은?","options":[{"t":"만지기 좋게 연하고 보드랍다","correct":true},{"t":"까칠까칠하게 일어나 있다","mis":"K2-1-u3-X07"},{"t":"뜨겁게 달아 있다","mis":"K2-1-u3-X07"}],"explanation":["보드라워요.","110쪽이에요.","기초 다지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#8','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C13',4,'sa','auto','『국어』 110쪽 — 「꽤 보드라운 느낌이 있다.」는 뜻의 낱말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u3-C13","difficulty":4,"kind":"sa","stem":"『국어』 110쪽 — 「꽤 보드라운 느낌이 있다.」는 뜻의 낱말을 쓰세요.","answer":["보드레하다"],"explanation":["보드레하다예요.","110쪽이에요.","느낌을 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#9','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C12',4,'essay','teacher','교실이나 집에 있는 식물 하나를 골라 이름이나 특징을 넣은 제목과, 꾸며 주는 말을 넣어 관찰한 모습을 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u3-C12","difficulty":4,"kind":"essay","stem":"교실이나 집에 있는 식물 하나를 골라 이름이나 특징을 넣은 제목과, 꾸며 주는 말을 넣어 관찰한 모습을 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 제목: 하늘하늘 춤추는 강낭콩 / 연두색 떡잎 두 장이 동그랗게 펼쳐졌다. 줄기가 하루가 다르게 쑥쑥 자란다.","scoring_points":["이름이나 특징을 넣은 제목을 썼어요","꾸며 주는 말을 넣어 관찰한 모습을 썼어요"]},"explanation":["관찰 일기예요.","106쪽이에요.","지도서 149쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#10','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C13',4,'essay','teacher','108쪽 그림을 떠올려 장면을 설명하는 문장을 꾸며 주는 말을 넣어 두 문장 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u3-C13","difficulty":4,"kind":"essay","stem":"108쪽 그림을 떠올려 장면을 설명하는 문장을 꾸며 주는 말을 넣어 두 문장 쓰세요.","answer_guide":{"answer":"예: 귀여운 강아지가 할머니 옆에서 꼬리를 살랑살랑 흔든다. 바람개비가 빙글빙글 신나게 돌아간다.","scoring_points":["꾸며 주는 말을 넣었어요","장면을 설명하는 문장을 두 개 썼어요"]},"explanation":["장면 설명이에요.","108쪽이에요.","지도서 152쪽이에요."],"asset":{"type":"scene","icon":"🏡","text":"『국어』 108쪽 — 장독대에 감꽃이 떨어지고, 바람개비가 돌고, 할머니 옆에 강아지가 있는 마당"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#1','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C1',1,'mc','auto','글 ㉯에서 「옥수수밭」을 꾸며 주는 말은?',ARRAY['K2-1-u3-X02']::text[],false,'{"seq":1,"concept":"K2-1-u3-C1","difficulty":1,"kind":"mc","stem":"글 ㉯에서 「옥수수밭」을 꾸며 주는 말은?","options":[{"t":"넓은","correct":true},{"t":"할머니","mis":"K2-1-u3-X02"},{"t":"오늘","mis":"K2-1-u3-X02"}],"explanation":["넓은이에요.","74쪽이에요.","꾸며 줘요."],"asset":{"type":"passage","lines":["㉮ 오늘 할머니, 할아버지와 옥수수밭에 갔다.","    할아버지께서 나를 보고 웃으셨다.","㉯ 오늘 할머니, 할아버지와 넓은 옥수수밭에 갔다.","    할아버지께서 나를 보고 활짝 웃으셨다."],"title":"『국어』 74쪽 글 ㉮와 글 ㉯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
