INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#4','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C4',1,'mc','auto','「(    ) 딸기를 먹었다.」 알맞은 말은?',ARRAY['K2-1-u3-X04']::text[],false,'{"seq":4,"concept":"K2-1-u3-C4","difficulty":1,"kind":"mc","stem":"「(    ) 딸기를 먹었다.」 알맞은 말은?","options":[{"t":"빨간","correct":true},{"t":"빠르게","mis":"K2-1-u3-X04"},{"t":"활짝","mis":"K2-1-u3-X04"}],"explanation":["빨간이에요.","77쪽이에요.","딸기를 꾸며요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#5','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C5',1,'mc','auto','땅콩이 열리는 식물의 꽃 색은?',ARRAY['K2-1-u3-X06']::text[],false,'{"seq":5,"concept":"K2-1-u3-C5","difficulty":1,"kind":"mc","stem":"땅콩이 열리는 식물의 꽃 색은?","options":[{"t":"노란색","correct":true},{"t":"빨간색","mis":"K2-1-u3-X06"},{"t":"파란색","mis":"K2-1-u3-X06"}],"explanation":["노란색이에요.","92쪽이에요.","노랑 꽃이에요."],"asset":{"type":"passage","lines":["땅콩은 새싹이 쑥쑥 자라 노란 꽃을 피워요.","열매는 땅속에서 맺혀요. 올록볼록 껍데기 속에 고소한 땅콩이 있어요.","포도는 덩굴손이 버팀대를 감고 뻗어 가요.","송알송알 보랏빛 포도가 탐스럽게 열려요.","개구리밥은 물 위에 떠서 자라는 풀이에요.","개구리가 물에서 나올 때 입가에 밥풀처럼 붙는다고 붙은 이름이래요."],"title":"『국어』 80~91쪽 「식물은 어떻게 자랄까?」(유다정) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
