INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#22','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C5',3,'mc','auto','「식물은 어떻게 자랄까?」에서 얻을 수 있는 가장 중요한 정보는?',ARRAY['K2-1-u3-X06']::text[],false,'{"seq":22,"concept":"K2-1-u3-C5","difficulty":3,"kind":"mc","stem":"「식물은 어떻게 자랄까?」에서 얻을 수 있는 가장 중요한 정보는?","options":[{"t":"식물마다 자라는 모습이 다양하다는 것","correct":true},{"t":"모든 식물은 똑같이 자란다는 것","mis":"K2-1-u3-X06"},{"t":"식물은 물에서만 자란다는 것","mis":"K2-1-u3-X06"}],"explanation":["다양해요.","지도서 133쪽이에요.","식물 정보예요."],"asset":{"type":"passage","lines":["땅콩은 새싹이 쑥쑥 자라 노란 꽃을 피워요.","열매는 땅속에서 맺혀요. 올록볼록 껍데기 속에 고소한 땅콩이 있어요.","포도는 덩굴손이 버팀대를 감고 뻗어 가요.","송알송알 보랏빛 포도가 탐스럽게 열려요.","개구리밥은 물 위에 떠서 자라는 풀이에요.","개구리가 물에서 나올 때 입가에 밥풀처럼 붙는다고 붙은 이름이래요."],"title":"『국어』 80~91쪽 「식물은 어떻게 자랄까?」(유다정) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#23','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C1',4,'sa','auto','「오늘 할머니, 할아버지와 (    ) 옥수수밭에 갔다.」 글 ㉯의 꾸며 주는 말을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u3-C1","difficulty":4,"kind":"sa","stem":"「오늘 할머니, 할아버지와 (    ) 옥수수밭에 갔다.」 글 ㉯의 꾸며 주는 말을 쓰세요.","answer":["넓은"],"explanation":["넓은이에요.","74쪽이에요.","옥수수밭을 꾸며요."],"asset":{"type":"passage","lines":["㉮ 오늘 할머니, 할아버지와 옥수수밭에 갔다.","    할아버지께서 나를 보고 웃으셨다.","㉯ 오늘 할머니, 할아버지와 넓은 옥수수밭에 갔다.","    할아버지께서 나를 보고 활짝 웃으셨다."],"title":"『국어』 74쪽 글 ㉮와 글 ㉯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#24','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C1',4,'essay','teacher','지도서 154~155쪽 평가 — 꾸며 주는 말을 사용해 자신을 소개하는 문장을 두 개 쓰세요(좋아하는 음식·색·취미·꿈 등).','{}'::text[],false,'{"seq":24,"concept":"K2-1-u3-C1","difficulty":4,"kind":"essay","stem":"지도서 154~155쪽 평가 — 꾸며 주는 말을 사용해 자신을 소개하는 문장을 두 개 쓰세요(좋아하는 음식·색·취미·꿈 등).","answer_guide":{"answer":"예: 저는 매콤한 떡볶이를 정말 좋아하는 나예요. 저는 커서 멋진 수의사가 되고 싶어요.","scoring_points":["자신을 소개하는 문장을 두 개 썼어요","꾸며 주는 말을 넣었어요"]},"explanation":["자신을 소개해요.","지도서 155쪽이에요.","꾸며 주는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#25','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C11',4,'essay','teacher','지도서 156~157쪽 평가 — 이번 주에 겪은 일 가운데 가장 인상 깊은 일을 골라 「때와 장소 / 있었던 일 / 생각이나 느낌」을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u3-C11","difficulty":4,"kind":"essay","stem":"지도서 156~157쪽 평가 — 이번 주에 겪은 일 가운데 가장 인상 깊은 일을 골라 「때와 장소 / 있었던 일 / 생각이나 느낌」을 쓰세요.","answer_guide":{"answer":"예: 수요일 점심시간, 운동장 / 친구들과 이어달리기를 했다 / 바통을 놓칠까 봐 조마조마했지만 끝까지 달려서 뿌듯했다.","scoring_points":["때와 장소를 썼어요","있었던 일을 썼어요","생각이나 느낌을 썼어요"]},"explanation":["일기 계획이에요.","지도서 157쪽이에요.","인상 깊은 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
