INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#22','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C6',3,'mc','auto','「땅속에서 조롱조롱 열매를 맺었구나.」에서 떠오르는 모습은?',ARRAY['K2-1-u3-X07','K2-1-u3-X06']::text[],false,'{"seq":22,"concept":"K2-1-u3-C6","difficulty":3,"kind":"mc","stem":"「땅속에서 조롱조롱 열매를 맺었구나.」에서 떠오르는 모습은?","options":[{"t":"작은 땅콩이 줄기에 많이 매달린 모습","correct":true},{"t":"땅콩이 하나만 있는 모습","mis":"K2-1-u3-X07"},{"t":"땅콩이 하늘에 뜬 모습","mis":"K2-1-u3-X06"}],"explanation":["많이 매달렸어요.","82쪽이에요.","낱말 알기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#23','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C5',4,'sa','auto','덩굴손이 버팀대를 감고 뻗어 가는 나무에서 열리는 보랏빛 과일을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u3-C5","difficulty":4,"kind":"sa","stem":"덩굴손이 버팀대를 감고 뻗어 가는 나무에서 열리는 보랏빛 과일을 쓰세요.","answer":["포도"],"explanation":["포도예요.","86쪽이에요.","송알송알 열려요."],"asset":{"type":"passage","lines":["땅콩은 새싹이 쑥쑥 자라 노란 꽃을 피워요.","열매는 땅속에서 맺혀요. 올록볼록 껍데기 속에 고소한 땅콩이 있어요.","포도는 덩굴손이 버팀대를 감고 뻗어 가요.","송알송알 보랏빛 포도가 탐스럽게 열려요.","개구리밥은 물 위에 떠서 자라는 풀이에요.","개구리가 물에서 나올 때 입가에 밥풀처럼 붙는다고 붙은 이름이래요."],"title":"『국어』 80~91쪽 「식물은 어떻게 자랄까?」(유다정) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#24','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C4',4,'essay','teacher','「강아지가 짖었다.」에 꾸며 주는 말을 넣어 더 자세한 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u3-C4","difficulty":4,"kind":"essay","stem":"「강아지가 짖었다.」에 꾸며 주는 말을 넣어 더 자세한 문장으로 쓰세요.","answer_guide":{"answer":"예: 작은 강아지가 멍멍 크게 짖었다.","scoring_points":["꾸며 주는 말을 넣었어요","더 자세한 문장이 되었어요"]},"explanation":["자세하게요.","74쪽이에요.","지도서 127쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#25','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C11',4,'essay','teacher','인상 깊은 일 하나로 꾸며 주는 말을 넣어 3~4문장의 일기를 쓰세요(생각이나 느낌 넣기).','{}'::text[],false,'{"seq":25,"concept":"K2-1-u3-C11","difficulty":4,"kind":"essay","stem":"인상 깊은 일 하나로 꾸며 주는 말을 넣어 3~4문장의 일기를 쓰세요(생각이나 느낌 넣기).","answer_guide":{"answer":"예: 오늘 점심시간에 짝과 운동장에서 줄넘기를 했다. 처음에는 줄이 자꾸 발에 걸렸다. 열 번을 넘게 쉬지 않고 넘었을 때 가슴이 콩닥콩닥 뛰었다. 정말 뿌듯했다.","scoring_points":["언제·어디에서·누구와·무엇을 썼어요","생각이나 느낌을 썼어요","꾸며 주는 말을 넣었어요"]},"explanation":["일기예요.","105쪽이에요.","평가 자료 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#1','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C1',1,'mc','auto','꾸며 주는 말은 무엇을 자세하게 해 주나요?',ARRAY['K2-1-u3-X01']::text[],false,'{"seq":1,"concept":"K2-1-u3-C1","difficulty":1,"kind":"mc","stem":"꾸며 주는 말은 무엇을 자세하게 해 주나요?","options":[{"t":"뒤에 오는 말의 뜻","correct":true},{"t":"문장의 길이","mis":"K2-1-u3-X01"},{"t":"글씨 모양","mis":"K2-1-u3-X01"}],"explanation":["뒤에 오는 말이에요.","74쪽이에요.","도우미 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
