INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#16','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C8',2,'match','auto','소율이가 겪은 일과 시간을 이어 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u3-C8","difficulty":2,"kind":"match","stem":"소율이가 겪은 일과 시간을 이어 보세요.","pairs":[{"l":"아침","r":"교통 봉사하시는 분께 인사"},{"l":"낮","r":"운동장에서 달리기"},{"l":"저녁","r":"도서관에서 그림책 읽기"}],"mis":"K2-1-u3-X11","explanation":["시간 순서예요.","96쪽이에요.","정리해요."],"asset":{"type":"passage","lines":["아침 — 맑은 하늘을 보고 기분이 좋았다. 교통 봉사하시는 분께 인사했다.","낮 — 화단에서 봄철 식물을 관찰하고, 운동장에서 달리기를 했다.","저녁 — 도서관에 가서 동생과 그림책을 읽었다."],"title":"『국어』 94~96쪽 소율이의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
