INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#24','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C7',4,'essay','teacher','국어활동 49쪽 — 독도에 사는 괭이갈매기의 모습을 꾸며 주는 말을 넣어 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u3-C7","difficulty":4,"kind":"essay","stem":"국어활동 49쪽 — 독도에 사는 괭이갈매기의 모습을 꾸며 주는 말을 넣어 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 우리나라 독도에는 멋진 괭이갈매기가 삽니다. 어미 괭이갈매기는 먹이를 물고 뒤뚱뒤뚱 아기에게 갑니다.","scoring_points":["괭이갈매기의 모습을 썼어요","꾸며 주는 말을 넣었어요"]},"explanation":["짧은 글이에요.","국어활동 49쪽이에요.","예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
