INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#15','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C12',2,'mc','auto','요리 일기의 마지막 문장 「뛸 듯이 행복했다.」는 어떤 부분인가요?',ARRAY['K2-1-u3-X14','K2-1-u3-X10']::text[],false,'{"seq":15,"concept":"K2-1-u3-C12","difficulty":2,"kind":"mc","stem":"요리 일기의 마지막 문장 「뛸 듯이 행복했다.」는 어떤 부분인가요?","options":[{"t":"겪은 일에 대한 생각이나 느낌","correct":true},{"t":"날짜와 날씨","mis":"K2-1-u3-X14"},{"t":"요리 재료","mis":"K2-1-u3-X10"}],"explanation":["느낌이에요.","지도서 151쪽이에요.","뛸 듯이예요."],"asset":{"type":"passage","lines":["20○○년 4월 30일 수요일 · 날씨: 미세 먼지 때문에 여기저기 갑갑","제목: 맛있는 간장달걀볶음밥","매끼 요리해 주시는 엄마를 위해 오늘은 내가 요리사가 되기로 했다.","달걀을 저어 익히고 파기름을 낸 뒤 밥과 함께 볶았다.","사랑하는 엄마께서 맛있게 드셔 주셔서 뛸 듯이 행복했다."],"title":"지도서 151쪽 요리 일기 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
